-- Migration: exam_tactics breakdown backfill, part 2/12
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]already[[/q]] olumlu cümlelerde beklenenden önce gerçekleşmiş bir şeyi vurgular; [[q]]yet[[/q]] olumsuz/soru cümlelerinde \"henüz\" anlamıyla cümle SONUNDA kullanılır; [[q]]still[[/q]] devam eden bir durumu vurgular ve HER ZAMAN fiilden ÖNCE gelir.", "items": [{"heading": "already: Olumlu Cümlede Beklenenden Önce", "body": [{"type": "text", "text": "[[amber]]already[[/amber]] OLUMLU cümlelerde, beklenenden önce ya da şu ana kadar gerçekleşmiş bir şeyi vurgular ve genelde yardımcı fiille ana fiil ARASINA ([[q]]has already finished[[/q]]) ya da cümle sonuna yerleşir."}]}, {"heading": "yet: Olumsuz / Soru Cümlesinde Cümle Sonunda", "body": [{"type": "text", "text": "[[amber]]yet[[/amber]] genellikle OLUMSUZ ve SORU cümlelerinde \"henüz\" anlamıyla cümle SONUNDA kullanılır ([[q]]Haven't you finished yet?[[/q]])."}]}, {"heading": "still: Devam Eden Durum — HER ZAMAN Fiilden Önce", "badge": "🔥 En Sık Tuzak", "body": [{"type": "text", "text": "[[amber]]still[[/amber]] devam etmekte olan bir durumu vurgular ve HER ZAMAN yardımcı fiilden/ana fiilden ÖNCE gelir ([[q]]is still waiting[[/q]], [[q]]still haven't received[[/q]]) — \"still\" cümle sonunda [[bad]]KULLANILMAZ[[/bad]], bu YDS'nin sevdiği bir tuzaktır."}, {"type": "example_check", "correct": "is still waiting", "wrong_note": "bir şıkta \"still\" cümle sonunda görülürse o şık kesinlikle yanlıştır"}]}], "examples": [{"sentence": "Have you received a reply from the university yet?", "answer_word": "yet", "reasoning": "Soru cümlesi ve \"henüz\" anlamı aranıyor, kelime cümle sonunda → doğru cevap [[right]]\"yet\"[[/right]]'tir; [[wrong]]\"already\"[[/wrong]] bu konumda ve bu bağlamda doğal değildir çünkü \"already\" tipik olarak olumlu/beklenti bildiren cümlelerde kullanılır."}, {"sentence": "We still haven't heard back from the embassy about our visa application.", "answer_word": "still", "reasoning": "Devam eden, bitmemiş bir durum (hâlâ cevap yok) ve kelime yardımcı fiilden ÖNCE konumlanmış → doğru cevap [[right]]\"still\"[[/right]]'dir; [[wrong]]\"yet\"[[/wrong]] bu konumda (cümle başında/ortasında, cümle sonunda değil) kullanılamaz, \"yet\" cümle sonuna yerleşmelidir."}, {"sentence": "To everyone's surprise, the young lawyer had already won two major cases before her thirtieth birthday.", "answer_word": "already", "reasoning": "Cümle olumlu ve beklenenden önce gerçekleşmiş bir başarıyı vurguluyor, kelime yardımcı fiil ile ana fiil ARASINA yerleşiyor → doğru cevap [[right]]\"already\"[[/right]]'dir; [[wrong]]\"yet\"[[/wrong]] bu konumda kullanılmaz, çünkü \"yet\" sadece olumsuz/soru cümlelerinin SONUNDA yer alır."}, {"sentence": "Despite months of negotiations, the two companies still haven't reached a final agreement on the merger.", "answer_word": "still", "reasoning": "Durum hâlâ devam ettiği (anlaşma sağlanamamış) ve kelime yardımcı fiilden ÖNCE konumlandığı için doğru cevap [[right]]\"still\"[[/right]]'dir; [[wrong]]\"yet\"[[/wrong]] burada yanlıştır çünkü \"yet\" cümle ortasında değil, cümle SONUNDA kullanılabilirdi."}]}$tagbd$::jsonb WHERE id = '01161703-c7c9-4589-9c08-9dd5924ffce8';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]-ly[[/q]] eki genellikle bir sıfatı zarfa çevirir [[pair]]quick->quickly[[/pair]], AMA [[b]]friendly, lovely, lonely, silly, elderly, likely, costly, daily, deadly, cowardly, timely[[/b]] gibi kelimeler -ly ile bitmesine RAĞMEN kendileri zaten birer SIFATTIR.", "items": [{"heading": "Zaten Sıfat Olan \"-ly\" Kelimeler", "badge": "İstisna Liste", "body": [{"type": "text", "text": "[[amber]]friendly, lovely, lonely, silly, elderly, likely, costly, daily, deadly, cowardly, timely[[/amber]] gibi kelimeler -ly ile bitmesine RAĞMEN kendileri zaten birer SIFATTIR — bunların [[bad]]\"-lyly\"[[/bad]] şeklinde ayrı bir zarf hali YOKTUR."}]}, {"heading": "Nasıl Kullanılır? İsim Önünde veya \"be\"den Sonra", "body": [{"type": "text", "text": "Bu kelimeler bir fiili değil bir İSMİ niteler veya [[q]]be[[/q]] fiilinden sonra kullanılır ([[pair]]friendly->a friendly dog[[/pair]], [[dark]]She is lovely[[/dark]])."}]}, {"heading": "Fiili Nitelemek İçin: Çevre İfade Kullan", "body": [{"type": "text", "text": "Bir cümlede bu kelimelerden biri bir FİİLİ nitelemek için kullanılmaya çalışılıyorsa (zarf konumunda), bu yanlıştır — doğru yol [[ok]]\"in a friendly way/manner\"[[/ok]] gibi bir çevre ifade kullanmaktır."}, {"type": "example_check", "correct": "greeted everyone in a friendly way", "wrong_note": "sadece \"friendly\" kullanmak yanlıştır çünkü \"friendlily\" diye bir kelime yoktur"}]}], "examples": [{"sentence": "The new neighbor greeted everyone in a friendly way.", "answer_word": "in a friendly way", "reasoning": "Burada \"greeted\" fiilini nitelemek için bir zarf gerekir, ama [[b]]\"friendly\"[[/b]] bir sıfattır, zarf değil → doğru cevap [[right]]\"in a friendly way\"[[/right]]'dir (ya da \"in a friendly manner\"); sadece [[wrong]]\"friendly\"[[/wrong]] kullanmak yanlıştır çünkü \"friendlily\" diye bir kelime yoktur."}, {"sentence": "My grandmother is a lovely old woman who always has a story to tell.", "answer_word": "lovely", "reasoning": "Burada bir İSMİ ([[b]]\"woman\"[[/b]]) niteleyen bir sıfat gerekiyor ve [[right]]\"lovely\"[[/right]] tam olarak bu konumda doğru kullanılan bir sıfattır — öğrenciler -ly ekine bakıp bunu yanlışlıkla bir zarf sanıp elediğinde hata yapar."}, {"sentence": "It is likely that the flight will be delayed due to the storm warning.", "answer_word": "likely", "reasoning": "Burada \"be\" fiilinden sonra bir SIFAT gerekir ve [[right]]\"likely\"[[/right]] (muhtemel) tam olarak bu konumda kullanılan, -ly ile biten ama aslında sıfat olan bir kelimedir; bunu zarf sanmak hataya yol açar."}, {"sentence": "Smoking is one of the most deadly habits a person can develop.", "answer_word": "deadly", "reasoning": "Burada bir İSMİ ([[b]]\"habits\"[[/b]]) niteleyen bir sıfat gerekiyor ve [[right]]\"deadly\"[[/right]] (öldürücü) -ly ile bitmesine rağmen zaten bir sıfattır; \"deadlily\" diye bir zarf yoktur."}]}$tagbd$::jsonb WHERE id = 'eaae34aa-c742-4953-9fc7-8761f01c71ad';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]be about to[[/q]] + yalın fiil, konuşma anından hemen sonra, neredeyse o anda gerçekleşecek bir eylemi anlatır — [[q]]going to[[/q]]dan (daha uzak, planlanmış niyet) ve [[q]]will[[/q]]den (anlık karar/genel tahmin) farkı kesin bir ÂNİLİK vurgusudur.", "items": [{"heading": "be about to + V1: Konuşma Anından Hemen Sonra", "body": [{"type": "text", "text": "[[amber]]be about to[[/amber]] + yalın fiil, konuşma anından hemen sonra, neredeyse o anda gerçekleşecek bir eylemi anlatır ve sıklıkla [[q]]just[[/q]] ile pekiştirilir ([[q]]just about to[[/q]])."}]}, {"heading": "was/were about to + V1 + when + Ani Olay", "body": [{"type": "text", "text": "Geçmiş zamanda [[q]]was/were about to + fiil[[/q]] kalıbı, gerçekleşmek ÜZEREYKEN bir şey tarafından KESİNTİYE UĞRAYAN bir eylemi anlatır ve neredeyse her zaman [[q]]when + ani bir geçmiş zaman olayı[[/q]] ile birlikte gelir."}, {"type": "example_check", "correct": "was about to leave when the phone rang", "wrong_note": "bu kalıp \"was about to + V + when + ani olay\" şeklinde sabitlenmiştir"}]}, {"heading": "Uzak Zaman İfadesi Varsa \"about to\" Elenir", "badge": "Tuzak", "body": [{"type": "text", "text": "Sınavda boşluktan sonra ya da cümle içinde [[q]]next month/next year[[/q]] gibi UZAK bir zaman ifadesi varsa [[bad]]\"about to\"[[/bad]] kesinlikle elenir — bu yapı sadece ÇOK YAKIN bir anı ifade eder, uzak planlar için [[ok]]\"going to\"[[/ok]] kullanılmalıdır."}]}], "examples": [{"sentence": "He was about to leave when his phone suddenly rang, so he sat back down and answered it.", "answer_word": "was about to leave", "reasoning": "Cümlede [[b]]\"when\"[[/b]] ile aniden kesintiye uğrayan, tam gerçekleşmek üzere olan bir eylem anlatılıyor → doğru cevap [[right]]\"was about to leave\"[[/right]]'dir; bu kalıp [[q]]was about to + V + when + ani olay[[/q]] şeklinde sabitlenmiştir."}, {"sentence": "She is going to finish her final exams next month, so she's already planning her summer trip.", "answer_word": "is going to", "reasoning": "Burada [[b]]\"next month\"[[/b]] ifadesi UZAK bir gelecek zamanı işaret ettiği için [[wrong]]\"about to\"[[/wrong]] (çok yakın an) yanlıştır — doğru cevap, önceden planlanmış bir niyeti anlatan [[right]]\"is going to\"[[/right]]'dur."}, {"sentence": "I was just about to call you when your message arrived, what a coincidence!", "answer_word": "about to", "reasoning": "[[b]]\"just\"[[/b]] kelimesi \"about to\" yapısını pekiştiren tipik bir sinyal kelimedir, çok yakın bir anı vurgular → doğru cevap [[right]]\"about to\"[[/right]]'dir."}, {"sentence": "Look at those dark clouds gathering overhead — it is about to pour down any minute now.", "answer_word": "is about", "reasoning": "Konuşma anından hemen sonra, neredeyse o anda gerçekleşecek somut bir gözleme dayalı tahmin var → doğru cevap [[right]]\"is about\"[[/right]]'tır (is about to); [[wrong]]\"will\"[[/wrong]] burada da kabul edilebilir bir tahmin olsa da \"about to\" yapısı buradaki ÂNİLİK vurgusunu daha güçlü karşılar."}]}$tagbd$::jsonb WHERE id = 'f1049e51-eb81-4d4f-a8f7-24e065ec1639';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]as...as[[/q]] yapısı iki şeyin EŞİT derecede olduğunu anlatır ve araya giren sıfat/zarf her zaman [[b]]YALIN[[/b]] (orijinal) halde kalır, ASLA [[bad]]\"-er\"[[/bad]] üstünlük eki almaz.", "items": [{"heading": "as...as İçinde Sıfat/Zarf HER ZAMAN Yalın Kalır", "badge": "Temel Kural", "body": [{"type": "text", "text": "[[q]]as...as[[/q]] yapısı iki şeyin EŞİT derecede olduğunu anlatır ve araya giren sıfat/zarf her zaman YALIN (orijinal) halde kalır, ASLA [[bad]]\"-er\"[[/bad]] üstünlük eki almaz — [[bad]]\"as taller as\"[[/bad]] gibi bir yapı İngilizce'de yoktur, doğrusu [[ok]]\"as tall as\"[[/ok]]'tır."}, {"type": "example_check", "correct": "as tall as", "wrong_note": "\"as taller as\" diye bir yapı yoktur"}]}, {"heading": "Olumsuz Eşitsizlik: not as...as / not so...as", "body": [{"type": "text", "text": "Olumsuz eşitsizlik için [[q]]not as...as[[/q]] veya (daha resmi) [[q]]not so...as[[/q]] kullanılır."}]}, {"heading": "Paralellik: Karşılaştırılan İki Taraf Aynı Yapıda Olmalı", "body": [{"type": "text", "text": "Karşılaştırılan iki öğe de aynı gramatik yapıda (paralel) olmalıdır: bir isimle bir isim, bir cümlecikle bir cümlecik karşılaştırılmalıdır. Bir şıkta \"as\" ile \"-er\" ekli bir sıfat/zarf bir arada görülürse bu şık kesinlikle yanlıştır."}]}], "examples": [{"sentence": "This smartphone is not as good as the previous model in terms of battery life.", "answer_word": "as good as", "reasoning": "Olumsuz bir eşitlik/karşılaştırma kuruluyor → doğru cevap [[right]]\"as good as\"[[/right]] (ya da \"as reliable as\") gibi yalın bir sıfatla \"as...as\" yapısıdır; [[wrong]]\"as better as\"[[/wrong]] seçeneği kesinlikle yanlıştır çünkü \"as...as\" içinde üstünlük eki (\"-er\") asla kullanılmaz."}, {"sentence": "She finished the marathon as quickly as her older brother did last year.", "answer_word": "as quickly as", "reasoning": "İki ayrı olayın (kendisinin ve kardeşinin koşusu) eşit derecede hızlı/iyi olduğu anlatılıyor, karşılaştırılan iki taraf da cümlecik yapısında → doğru cevap [[right]]\"as quickly as\"[[/right]]'tır; [[wrong]]\"as quicker as\"[[/wrong]] gibi bir seçenek yine aynı üstünlük-eki tuzağı yüzünden yanlıştır."}, {"sentence": "The new bridge is not as strong as the old one, which could handle much heavier loads.", "answer_word": "as strong as", "reasoning": "Olumsuz bir eşitlik karşılaştırması kuruluyor ve araya giren sıfat YALIN kalmalı → doğru cevap [[right]]\"as strong as\"[[/right]]'tır; [[wrong]]\"as stronger as\"[[/wrong]] seçeneği \"as...as\" yapısı içinde üstünlük eki (\"-er\") barındırdığı için kesinlikle yanlıştır."}, {"sentence": "For many students, learning a new language can be as difficult as mastering a musical instrument.", "answer_word": "as difficult as", "reasoning": "İki taraf da aynı gramatik yapıda (iki ayrı -ing öbeği) karşılaştırıldığı için yapı PARALELDİR ve boşluklara yalın sıfatla [[right]]\"as...as\"[[/right]] gelir; sıfat üstünlük eki alsaydı ([[wrong]]\"as more difficult as\"[[/wrong]]) hem paralellik hem de üstünlük-eki tuzağı yüzünden yanlış olurdu."}]}$tagbd$::jsonb WHERE id = '582b694d-306b-4cbc-86f0-f675f96716b0';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Cümlede özne bir işi KENDİSİ yapmıyor, bir BAŞKASINA YAPTIRIYORsa doğru yapı [[q]]have/get + nesne + V3 (past participle)[[/q]]'dir:", "items": [{"heading": "Doğru Yapı: have/get + nesne + V3", "badge": "Kalıp", "body": [{"type": "text", "text": "Nesneden sonra ASLA [[bad]]\"to\"[[/bad]] ya da [[bad]]V1[[/bad]] gelmez, sadece [[ok]]V3 (past participle)[[/ok]] gelir."}, {"type": "example_check", "correct": "I had my hair cut", "wrong_note": "\"have my car to repair\" ya da \"have my car repair\" kesinlikle yanlıştır"}]}, {"heading": "get ile have Arasındaki Nüans", "body": [{"type": "text", "text": "[[amber]]\"get\"[[/amber]] kullanıldığında anlam aynıdır ama biraz daha gayri resmidir ve bazen işin tamamlanması için ÇABA gösterildiği vurgusunu taşır: \"I got my passport renewed just in time\"."}]}, {"heading": "İstenmeyen Olaylar için de Kullanılır", "body": [{"type": "text", "text": "Bu yapı sadece bilinçli olarak yaptırılan işler için değil, başa gelen [[dark]]İSTENMEYEN[[/dark]] olaylar için de kullanılır: \"he had his wallet stolen\" (cüzdanı çalındı)."}]}, {"heading": "have my hair cut vs cut my hair", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Aynı fiille kurulan bu iki yapı [[dark]]TAMAMEN FARKLI[[/dark]] bir anlam taşır:"}], "meaning_pairs": [[{"word": "had my hair cut", "meaning": "saçımı (kuaföre) kestirdim — başkası yaptı"}, {"word": "cut my hair", "meaning": "saçımı kendim kestim", "variant": "wrong"}]], "warning_text": "İşi kimin yaptığına (özne mi, başkası mı) dikkat etmeden yapıyı seçmek bu sorularda neredeyse her zaman yanlış şıkkı seçtirir."}], "examples": [{"sentence": "I don't have time to fix the printer myself, so I'll have it repaired by the IT department tomorrow.", "answer_word": "have it repaired", "reasoning": "Özne işi kendisi yapmayıp BAŞKASINA yaptırdığı için doğru yapı [[right]]\"have ... repaired\"[[/right]]tir; [[wrong]]\"repair\"[[/wrong]] (V1) ya da [[wrong]]\"to repair\"[[/wrong]] bu kalıpta kullanılmaz."}, {"sentence": "She was so busy before the wedding that she had her dress altered by a professional tailor instead of sewing it herself.", "answer_word": "had her dress altered", "reasoning": "Yine iş başkasına yaptırıldığı için doğru cevap [[right]]\"had ... altered\"[[/right]] (V3) yapısıdır; [[wrong]]\"altering\"[[/wrong]] (-ing) ya da [[wrong]]\"alter\"[[/wrong]] (V1) bu kalıpta yanlıştır."}, {"sentence": "Every winter, we have our heating system serviced by a certified technician before the cold sets in.", "answer_word": "have our heating system serviced", "reasoning": "İş başkasına (teknisyene) yaptırıldığı için doğru yapı [[right]]\"have ... serviced\"[[/right]]tir; [[wrong]]\"service\"[[/wrong]] (V1) ya da [[wrong]]\"to service\"[[/wrong]] bu kalıpta kullanılmaz."}, {"sentence": "He was furious when he realized he had his wallet stolen while he was asleep on the train.", "answer_word": "had his wallet stolen", "reasoning": "Cüzdanın başına istenmeyen bir şekilde (hırsızlıkla) bir şey GELMESİ anlatıldığı için doğru yapı [[right]]\"had ... stolen\"[[/right]]dır (geçmişte bir geçmiş); bu kalıp sadece bilinçli olarak yaptırılan işler için değil, [[b]]başa gelen istenmeyen olaylar[[/b]] için de kullanılır."}]}$tagbd$::jsonb WHERE id = 'f8e72376-ebad-4130-94d1-291dff9e20ba';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Cümleler arasındaki mantıksal ilişkiyi önce belirle — doğru bağlaç bu ilişkiden kendini gösterir:", "items": [{"heading": "Dört İlişki Türü", "badge": "Önce İlişkiyi Belirle", "body": [{"type": "text", "text": "[[q]]Zıtlık/istisna[[/q]]: however, nevertheless, although, despite, in contrast"}, {"type": "text", "text": "[[q]]Sebep-sonuç[[/q]]: because, since, therefore, thus, as a result, consequently"}, {"type": "text", "text": "[[q]]Ekleme/pekiştirme[[/q]]: moreover, furthermore, in addition, not only...but also"}, {"type": "text", "text": "[[q]]Koşul[[/q]]: if, unless, provided that"}]}, {"heading": "Eleme Kuralları", "badge": "Çeldiricileri Ele", "body": [{"type": "text", "text": "[[amber]]\"therefore/thus\"[[/amber]] gibi sonuç bağlaçlarından önce net bir [[b]]sebep[[/b]] bulunmalıdır."}, {"type": "text", "text": "[[amber]]\"although\"[[/amber]] beklenmedik bir sonuçla eşleşirken, [[amber]]\"because\"[[/amber]] net bir sebep ister."}, {"type": "text", "text": "[[amber]]\"moreover/furthermore\"[[/amber]] aynı (olumlu veya olumsuz) tonda devam eder; zıtlık varsa elenir."}, {"type": "text", "text": "[[amber]]\"not only...but also\"[[/amber]] paralel yapı zorunlu kılar."}]}], "examples": [{"sentence": "The company invested heavily in new technology; as a result, its production costs decreased significantly.", "answer_word": "as a result", "reasoning": "Yatırım ([[b]]sebep[[/b]]) → maliyetlerin düşmesi ([[b]]sonuç[[/b]]) net bir neden-sonuç ilişkisi kurar. Doğru cevap [[right]]\"as a result\"[[/right]] ya da \"consequently\"dir; [[wrong]]\"however\"[[/wrong]] (zıtlık) veya [[wrong]]\"moreover\"[[/wrong]] (ekleme, aynı konuda devam) bu ilişkiyi karşılamadığı için elenir."}, {"sentence": "The university expanded its scholarship program; moreover, it opened three new research centers this year.", "answer_word": "moreover", "reasoning": "İki cümle de olumlu ve birbirine eklenen gelişmelerden bahsediyor, aralarında sebep-sonuç değil pekiştirme ilişkisi var → doğru cevap [[right]]\"moreover\"[[/right]] ya da \"in addition\"dır; [[wrong]]\"therefore\"[[/wrong]] (sonuç bağlacı) burada aralarında nedensellik olmadığı için yanlıştır."}, {"sentence": "The new regulation was expected to boost small businesses; however, overall revenue in the sector actually declined in the following months.", "answer_word": "however", "reasoning": "Beklenen olumlu sonuç (boost) ile gerçekleşen olumsuz durum (declined) arasında açık bir zıtlık var → doğru cevap [[right]]\"however\"[[/right]]dür; [[wrong]]\"therefore\"[[/wrong]] (sonuç bağlacı) burada iki cümle arasında bir neden-sonuç değil bir ÇELİŞKİ olduğu için yanlıştır."}, {"sentence": "The hotel offers a complimentary breakfast every morning; moreover, it provides a free shuttle service to and from the airport.", "answer_word": "moreover", "reasoning": "İki cümle de otelin sunduğu olumlu hizmetleri PEKİŞTİREREK sıralıyor, aralarında zıtlık veya nedensellik yok → doğru cevap [[right]]\"moreover\"[[/right]] ya da \"in addition\"dır; [[wrong]]\"as a result\"[[/wrong]] burada bir sonuç ilişkisi olmadığı için yanlıştır."}]}$tagbd$::jsonb WHERE id = 'c004c79a-c766-436f-9e28-b4857404ef42';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Tip 0 ve Tip 1 ikisi de [[q]]if + present simple[[/q]] ile başlar, ama ana cümlecikleri FARKLIDIR:", "items": [{"heading": "Tip 0 ve Tip 1 Kalıpları", "badge": "Temel Yapı", "sub_rules": [{"condition": "[[q]]Tip 0[[/q]] (genel/bilimsel gerçek) için:", "from": "if + present simple", "to": "present simple"}, {"condition": "[[q]]Tip 1[[/q]] (gelecekte mümkün durum) için:", "from": "if + present simple", "to": "will + V1"}]}, {"heading": "\"will\" Tuzağı", "body": [{"type": "text", "text": "If cümleciğinde [[bad]]\"will\"[[/bad]] ASLA kullanılmaz — bu YDS'nin en temel ve en sık sorulan kuralıdır."}, {"type": "example_check", "correct": "If it rains tomorrow, I will stay home", "wrong_note": "\"If it will rain\" her zaman yanlıştır"}]}, {"heading": "unless = if...not", "body": [{"type": "text", "text": "[[amber]]\"unless\"[[/amber]], [[q]]\"if...not\"[[/q]] anlamına gelir ve olumsuz bir if cümleciğinin yerini alır."}]}], "examples": [{"sentence": "If you heat ice, it melts.", "answer_word": "heat", "reasoning": "Genel bir bilimsel gerçek anlatıldığı için [[q]]Tip 0[[/q]] kullanılır, doğru cevap [[right]]\"heat\"[[/right]]tir (present simple), [[wrong]]\"will heat\"[[/wrong]] veya [[wrong]]\"heated\"[[/wrong]] değil."}, {"sentence": "If the weather improves tomorrow, we will go hiking in the mountains.", "answer_word": "improves", "reasoning": "Gelecekte gerçekleşmesi mümkün bir durum anlatıldığı için [[q]]Tip 1[[/q]] kullanılır, if cümleciğinde present simple gerekir → doğru cevap [[right]]\"improves\"[[/right]]tir, [[wrong]]\"will improve\"[[/wrong]] kullanmak if cümleciğinde asla doğru olmaz."}, {"sentence": "If you mix red and blue paint, you get purple.", "answer_word": "mix", "reasoning": "Genel, değişmeyen bir gerçek (renk karışımı) anlatıldığı için [[q]]Tip 0[[/q]] kullanılır, doğru cevap [[right]]\"mix\"[[/right]]tir (present simple)."}, {"sentence": "If the company doesn't invest in new technology soon, it will struggle to remain competitive.", "answer_word": "doesn't invest", "reasoning": "Gelecekte gerçekleşmesi mümkün bir durum anlatıldığı için [[q]]Tip 1[[/q]] kullanılır, if cümleciğinde present simple'ın olumsuz hali gerekir → doğru cevap [[right]]\"doesn't invest\"[[/right]]tir; [[wrong]]\"won't invest\"[[/wrong]] if cümleciğinde asla kullanılmaz."}]}$tagbd$::jsonb WHERE id = '8e4cad68-ff49-4324-a2ca-676cc5d8f832';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Tip 3, GEÇMİŞTE gerçekleşmemiş, artık değiştirilemeyecek bir durumu ve onun hayali sonucunu anlatır: [[q]]if + had + V3[[/q]], [[q]]would have + V3[[/q]]:", "items": [{"heading": "Tip 3 Kalıbı", "badge": "Temel Yapı", "body": [{"type": "text", "text": "Geçmişte gerçekleşmemiş bir durumu ve onun hayali sonucunu anlatır."}, {"type": "example_check", "correct": "If I had studied harder, I would have passed the exam", "wrong_note": "ama çalışmadım ve geçemedim — gerçekleşmemiş bir durum"}]}, {"heading": "\"would have\" Tuzağı", "body": [{"type": "text", "text": "If cümleciğinde [[bad]]\"would have\"[[/bad]] KULLANILMAZ ([[bad]]\"If I would have studied\"[[/bad]] yanlıştır), sadece [[ok]]\"had + V3\"[[/ok]] kullanılır."}]}, {"heading": "Sonuç Cümleciğinde Alternatifler", "body": [{"type": "text", "text": "Sonuç cümleciğinde [[amber]]would have[[/amber]] yerine [[amber]]could have[[/amber]] (yapabilirdi) veya [[amber]]might have[[/amber]] (belki yapardı) de gelebilir, anlam nüansına göre değişir."}]}], "examples": [{"sentence": "If he had left earlier, he wouldn't have missed the flight.", "answer_word": "had left", "reasoning": "Geçmişte gerçekleşmemiş bir durum (erken çıkmadı, uçağı kaçırdı) anlatıldığı için doğru cevap [[right]]\"had left\"[[/right]]tir, [[wrong]]\"would have left\"[[/wrong]] değil."}, {"sentence": "If they had invested in better equipment, the factory wouldn't have suffered such heavy losses.", "answer_word": "had invested", "reasoning": "Geçmişte gerçekleşmemiş bir durum (yatırım yapmadılar, zarar ettiler) anlatıldığı için doğru cevap [[right]]\"had invested\"[[/right]]tir; [[wrong]]\"would have invested\"[[/wrong]] if cümleciğinde asla kullanılmaz, bu YDS'nin en sık sorduğu Tip 3 tuzaklarından biridir."}, {"sentence": "If she had known about the heavy traffic on the highway, she would have left the house a full hour earlier.", "answer_word": "had known", "reasoning": "Geçmişte gerçekleşmemiş bir durum (trafiği bilmedi, erken çıkmadı) anlatıldığı için doğru cevap [[right]]\"had known\"[[/right]]dur, [[wrong]]\"would have known\"[[/wrong]] if cümleciğinde asla kullanılmaz."}, {"sentence": "If the team had practiced more consistently throughout the season, they wouldn't have lost the championship match so badly.", "answer_word": "had practiced", "reasoning": "Geçmişte gerçekleşmemiş bir durum (düzenli çalışmadılar, kaybettiler) anlatıldığı için doğru cevap [[right]]\"had practiced\"[[/right]]tir; bu yapı, if cümleciğinde [[bad]]\"would have\"[[/bad]] kullanmanın neden kesinlikle yanlış olduğunu gösteren klasik bir YDS tuzağıdır."}]}$tagbd$::jsonb WHERE id = 'aa7cbd8a-9edf-4baf-af4f-7caba80af43f';
